230	func (f *LaunchForm) SetWidth(w int) {
231		f.width = w
232		f.resizeInputs()
233	}
234	
235	func (f *LaunchForm) resizeInputs() {
236		// In two-column mode the left column is 55% of width; inputs sit below their label with 2-char indent.
237		inputWidth := f.width - 4
238		if f.width >= 100 {
239			inputWidth = f.width*55/100 - 4
240		}
241		inputWidth = max(inputWidth, 20)
242		f.nameInput.SetWidth(inputWidth)
243		f.entrypointInput.SetWidth(inputWidth)
244		f.envInput.SetWidth(inputWidth)
245		f.volInput.SetWidth(inputWidth)
246		f.userInput.SetWidth(inputWidth)
247		f.extraPortsInput.SetWidth(inputWidth)
248	}
249	
250	// Field indices follow the visual render order:
251	// 0:name  1:entrypoint  2:env  3:volumes  4:user  5:network  6..6+n-1:ports  6+n:extraPorts  6+n+1..+3:options  6+n+4:submit
252	const firstPortFieldOffset = 6
253	
254	func (f *LaunchForm) fieldEntrypoint() int        { return 1 }
255	func (f *LaunchForm) fieldEnv() int               { return 2 }
256	func (f *LaunchForm) fieldVolumes() int           { return 3 }
257	func (f *LaunchForm) fieldUser() int              { return 4 }
258	func (f *LaunchForm) fieldNetwork() int           { return 5 }
259	func (f *LaunchForm) firstPortField() int         { return firstPortFieldOffset }
260	func (f *LaunchForm) fieldExtraPorts() int        { return firstPortFieldOffset + len(f.ports) }
261	func (f *LaunchForm) fieldOptionRemove() int      { return firstPortFieldOffset + len(f.ports) + 1 }
262	func (f *LaunchForm) fieldOptionDetach() int      { return firstPortFieldOffset + len(f.ports) + 2 }
263	func (f *LaunchForm) fieldOptionInteractive() int { return firstPortFieldOffset + len(f.ports) + 3 }
264	func (f *LaunchForm) fieldSubmit() int            { return firstPortFieldOffset + len(f.ports) + 4 }
265	
266	// isPortField returns true if the given index corresponds to a port entry row
267	func (f *LaunchForm) isPortField(idx int) bool {
268		return idx >= f.firstPortField() && idx < f.firstPortField()+len(f.ports)
269	}
