		f.entrypointInput, cmd = f.entrypointInput.Update(msg)
		if newVal := f.entrypointInput.Value(); newVal != prev {
			verifyCmd := f.onEntrypointChanged(newVal)
			cmd = tea.Batch(cmd, verifyCmd)

